import sys
from datetime import datetime, timezone

def solve():
    try:
        with open(sys.argv[1], 'r') as f:
            data = json.load(f)
    except Exception:
        return

    if "as_of" not in data or "reminders" not in data:
        print(json.dumps([]))
        return

    as_of_str = data["as_of"]
    try:
        as_of_dt = datetime.fromisoformat(as_of_str)
    except ValueError:
        print(json.dumps([]))
        return

    # Ensure as_of is aware (it's stated to be offset-aware)
    if as_of_dt.tzinfo is None or as_of_dt.tzinfo.utcoffset(as_of_dt) is None:
        # This shouldn't happen based on the contract
        print(json.dumps([]))
        return

    valid_reminders = []

    for r in data["reminders"]:
        # Skip completed
        if r.get("completed", False):
            continue

        due_val = r.get("due")
        if due_val is None:
            continue

        if not isinstance(due_val, str):
            continue

        try:
            due_dt = datetime.fromisoformat(due_val)
        except ValueError:
            continue

        # Skip naive due
        if due_dt.tzinfo is None or due_dt.tzinfo.utcoffset(due_dt) is None:
            continue

        # Include if due <= as_of
        if due_dt <= as_of_dt:
            # Format due_utc as YYYY-MM-DDTHH:MM:SSZ
            # We must convert to UTC first.
            due_utc_dt = due_dt.astimezone(timezone.utc)
            # The requirement is YYYY-MM-DDTHH:MM:SSZ.
            # strftime handles this.
            due_utc_str = due_utc_dt.strftime('%Y-%m-%dT%H:%M:%SZ')

            valid_reminders.append({
                "id": r["id"],
                "title": r["title"],
                "due_utc": due_utc_str,
                "_due_dt": due_dt # used for sorting
            })

    # Sort by actual due instant then id
    valid_reminders.sort(key=lambda x: (x["_due_dt"], x["id"]))

    # Final output format
    output = []
    for vr in valid_reminders:
        output.append({
            "id": vr["id"],
            "title": vr["title"],
            "due_utc": vr["due_utc"]
        })

    print(json.dumps(output))

if __name__ == "__main__":
    solve()
